# %% pts/netrun/06_net/00_config/02_graph.pct.py 4
def _parse_graph_node(value: Any) -> NodeConfig | SubgraphConfig:
    """Parse a graph node, defaulting to NodeConfig when type is not specified."""
    if isinstance(value, (NodeConfig, SubgraphConfig)):
        return value
    if isinstance(value, dict):
        # Check if it's explicitly a subgraph
        if value.get("type") == "subgraph":
            return SubgraphConfig.model_validate(value)
        # Default to NodeConfig (handles both "node" and missing type)
        return NodeConfig.model_validate(value)
    raise ValueError(f"Invalid node config: {value}")

# Type alias for nodes that can be either regular nodes or subgraphs
# Uses BeforeValidator to default to NodeConfig when type is not specified
GraphNodeConfig = Annotated[
    NodeConfig | SubgraphConfig,
    BeforeValidator(_parse_graph_node)
]

# %% pts/netrun/06_net/00_config/02_graph.pct.py 5
class GraphConfig(VarResolvableModel):
    """Configuration for a complete flow-based network graph.

    Example:
        config = GraphConfig(
            nodes=[
                NodeConfig(
                    name="A",
                    out_ports={"out": PortConfig()},
                ),
                NodeConfig(
                    name="B",
                    in_ports={"in": PortConfig()},
                    in_salvo_conditions={
                        "default": SalvoConditionConfig(
                            max_salvos=MaxSalvosFiniteConfig(max=1),
                            ports={"in": PacketCountAllConfig()},
                            term=SalvoConditionTermPortConfig(
                                port_name="in",
                                state=PortStateNonEmptyConfig(),
                            ),
                        ),
                    },
                ),
            ],
            edges=[
                EdgeConfig(source_str="A.out", target_str="B.in"),
            ],
        )
        graph = config.get_graph()
    """
    nodes: list[GraphNodeConfig]
    """List of nodes (NodeConfig) and/or subgraphs (SubgraphConfig)."""

    edges: list[EdgeConfig] = Field(default_factory=list)

    extra: dict[str, Any] = Field(default_factory=dict)
    """Arbitrary extra data for the graph.

    Can be used to store descriptions, UI viewport state, or any other
    tool-specific data that should be preserved across serialization.
    """

    def resolve(self, base_path: Path | None = None, net_config: 'Any | None' = None) -> "GraphConfig":
        """Return a resolved copy with all subgraphs flattened and nodes resolved.

        This method:
        1. Flattens all SubgraphConfig into NodeConfig with prefixed names
        2. Rewrites edges to use the prefixed names
        3. Adds edges connecting exposed ports to parent graph edges
        4. Resolves all node factories and import paths
        5. Validates no name collisions exist

        Args:
            base_path: Base path for resolving relative file paths in subgraphs.
            net_config: NetConfig instance for resolving project root and passed
                        to factory functions.

        Returns:
            A new GraphConfig with only NodeConfig (no SubgraphConfig) and all
            edges properly connected.

        Raises:
            ValueError: If name collisions are detected after resolution.
        """
        resolved_nodes: list[NodeConfig] = []
        resolved_edges: list[EdgeConfig] = list(self.edges)

        # Track subgraph port mappings for edge rewriting
        subgraph_in_mappings: dict[str, dict[str, str]] = {}
        subgraph_out_mappings: dict[str, dict[str, str]] = {}

        # First pass: resolve subgraphs and collect regular nodes
        for node in self.nodes:
            if isinstance(node, SubgraphConfig):
                # Resolve subgraph to flat nodes and edges
                sg_nodes, sg_edges, in_mapping, out_mapping = node.resolve(base_path=base_path)
                # Resolve factory nodes inside subgraphs (bug fix)
                resolved_nodes.extend(n.resolve(net_config=net_config) for n in sg_nodes)
                resolved_edges.extend(sg_edges)
                subgraph_in_mappings[node.name] = in_mapping
                subgraph_out_mappings[node.name] = out_mapping
            else:
                # Regular node - resolve factories
                resolved = node.resolve(net_config=net_config)
                if isinstance(resolved, SubgraphConfig):
                    # Factory returned a subgraph — flatten it
                    sg_nodes, sg_edges, in_mapping, out_mapping = resolved.resolve(base_path=base_path)
                    resolved_nodes.extend(n.resolve(net_config=net_config) for n in sg_nodes)
                    resolved_edges.extend(sg_edges)
                    subgraph_in_mappings[resolved.name] = in_mapping
                    subgraph_out_mappings[resolved.name] = out_mapping
                else:
                    resolved_nodes.append(resolved)

        # Second pass: rewrite edges that connect to subgraph exposed ports
        final_edges: list[EdgeConfig] = []
        for edge in resolved_edges:
            source = edge.get_source()
            target = edge.get_target()

            new_source = source
            new_target = target

            # Check if source refers to a subgraph's exposed output port
            if source.node_name in subgraph_out_mappings:
                mapping = subgraph_out_mappings[source.node_name]
                if source.port_name in mapping:
                    # Map to internal node.port
                    mapped = mapping[source.port_name]
                    internal_node, internal_port = mapped.rsplit(".", 1)
                    new_source = PortRefConfig(
                        node_name=internal_node,
                        port_type="output",
                        port_name=internal_port,
                    )

            # Check if target refers to a subgraph's exposed input port
            if target.node_name in subgraph_in_mappings:
                mapping = subgraph_in_mappings[target.node_name]
                if target.port_name in mapping:
                    # Map to internal node.port
                    mapped = mapping[target.port_name]
                    internal_node, internal_port = mapped.rsplit(".", 1)
                    new_target = PortRefConfig(
                        node_name=internal_node,
                        port_type="input",
                        port_name=internal_port,
                    )

            final_edges.append(EdgeConfig(source=new_source, target=new_target, dependency=edge.dependency))

        # Auto-apply default DependencyRequestConfig for nodes with dependency edges
        dep_target_nodes = set()
        for edge in final_edges:
            if edge.dependency:
                dep_target_nodes.add(edge.get_target().node_name)

        for node in resolved_nodes:
            if node.name in dep_target_nodes and node.dependency_request is None:
                node.dependency_request = DependencyRequestConfig()

        # Validate no name collisions
        node_names = [n.name for n in resolved_nodes]
        seen_names: set[str] = set()
        for name in node_names:
            if name in seen_names:
                raise ValueError(f"Node name collision after subgraph resolution: '{name}'")
            # Also check for prefix conflicts
            for seen in seen_names:
                if name.startswith(f"{seen}.") or seen.startswith(f"{name}."):
                    raise ValueError(
                        f"Node name prefix collision: '{name}' conflicts with '{seen}'. "
                        "Node names cannot be prefixes of other node names when using subgraphs."
                    )
            seen_names.add(name)

        # Resolve $var refs per-node with merged variables (net-level + node-level override)
        net_var_models: dict[str, 'NodeVariable'] = {}
        if net_config is not None and getattr(net_config, 'node_vars', None):
            for name, var in net_config.node_vars.items():
                if var.inherit:
                    raise ValueError(f"Net-level variable '{name}' must not have inherit=True")
                net_var_models[name] = var

        net_vars = {name: var.resolve_value() for name, var in net_var_models.items()}

        for i, node in enumerate(resolved_nodes):
            node_exec_vars = {}
            if node.execution_config and node.execution_config.node_vars:
                for name, var in node.execution_config.node_vars.items():
                    if var.inherit:
                        if name not in net_var_models:
                            raise ValueError(
                                f"Node '{node.name}' variable '{name}' has inherit=True "
                                f"but no net-level variable '{name}' exists"
                            )
                        global_var = net_var_models[name]
                        if var.value is not None:
                            # Override just the value, use global type/options/optional
                            effective = NodeVariable(
                                value=var.value,
                                type=global_var.type,
                                options=global_var.options,
                                optional=global_var.optional,
                            )
                            node_exec_vars[name] = effective.resolve_value()
                        else:
                            # Inherit everything from global
                            node_exec_vars[name] = global_var.resolve_value()
                    else:
                        node_exec_vars[name] = var.resolve_value()
            merged_vars = {**net_vars, **node_exec_vars}
            if merged_vars:
                new_node = node.resolve_var_refs(merged_vars)
                if new_node is not node:
                    resolved_nodes[i] = new_node

        return GraphConfig(nodes=resolved_nodes, edges=final_edges, extra=self.extra)

    def validate(self) -> list[ConfigValidationError]:
        """Validate graph structure without requiring factory resolution.

        Checks:
        - Duplicate node names
        - Empty node names
        - Fan-out (output port connected to multiple edges)
        - Edge references to non-existent nodes
        - Edge references to non-existent ports (non-factory nodes only)
        - Per-node salvo condition port validation (via NodeConfig.validate)

        Returns:
            List of ConfigValidationError (empty if valid).
        """
        errors: list[ConfigValidationError] = []

        # Build node name set and check duplicates/empty
        node_names: set[str] = set()
        for idx, node in enumerate(self.nodes):
            if not node.name:
                errors.append(ConfigValidationError(
                    loc=["nodes", idx, "name"],
                    msg=f"Node at index {idx} has an empty name",
                    type="empty_node_name",
                ))
            elif node.name in node_names:
                errors.append(ConfigValidationError(
                    loc=["nodes", idx, "name"],
                    msg=f"Duplicate node name '{node.name}'",
                    type="duplicate_node_name",
                ))
            else:
                node_names.add(node.name)

        # Build port lookup for non-factory nodes
        # factory nodes: skip port checks (ports unknown until resolution)
        # subgraph nodes: use exposed_in_ports/exposed_out_ports
        node_in_ports: dict[str, set[str] | None] = {}  # None = skip check
        node_out_ports: dict[str, set[str] | None] = {}

        for node in self.nodes:
            if isinstance(node, SubgraphConfig):
                node_in_ports[node.name] = set(node.exposed_in_ports.keys())
                node_out_ports[node.name] = set(node.exposed_out_ports.keys())
            elif node.factory is not None:
                node_in_ports[node.name] = None
                node_out_ports[node.name] = None
            else:
                node_in_ports[node.name] = set(node.in_ports.keys())
                node_out_ports[node.name] = set(node.out_ports.keys())

        # Validate edges: node existence, port existence, collect sources for fan-out
        source_keys: dict[str, list[int]] = {}  # "node.port" -> list of edge indices

        for idx, edge in enumerate(self.edges):
            try:
                source = edge.get_source()
                target = edge.get_target()
            except ValueError:
                # Malformed edge string — pydantic already catches this
                continue

            # Check source node exists
            if source.node_name not in node_names:
                errors.append(ConfigValidationError(
                    loc=["edges", idx],
                    msg=f"Edge source references non-existent node '{source.node_name}'",
                    type="missing_node",
                ))
            else:
                # Check source port exists (if ports are known)
                # Signal ports are auto-generated during resolve(), so skip them here
                out_ports = node_out_ports.get(source.node_name)
                if out_ports is not None and source.port_name not in out_ports and not is_signal_port(source.port_name):
                    errors.append(ConfigValidationError(
                        loc=["edges", idx],
                        msg=f"Edge source references non-existent port '{source.port_name}' on node '{source.node_name}'",
                        type="missing_port",
                    ))

            # Check target node exists
            if target.node_name not in node_names:
                errors.append(ConfigValidationError(
                    loc=["edges", idx],
                    msg=f"Edge target references non-existent node '{target.node_name}'",
                    type="missing_node",
                ))
            else:
                # Check target port exists (if ports are known)
                in_ports = node_in_ports.get(target.node_name)
                if in_ports is not None and target.port_name not in in_ports:
                    errors.append(ConfigValidationError(
                        loc=["edges", idx],
                        msg=f"Edge target references non-existent port '{target.port_name}' on node '{target.node_name}'",
                        type="missing_port",
                    ))

            # Collect source key for fan-out detection
            src_key = f"{source.node_name}.{source.port_name}"
            source_keys.setdefault(src_key, []).append(idx)

        # Detect fan-out
        for src_key, edge_indices in source_keys.items():
            if len(edge_indices) > 1:
                for idx in edge_indices:
                    errors.append(ConfigValidationError(
                        loc=["edges", idx],
                        msg=f"Fan-out: output port '{src_key}' is connected by multiple edges (indices {edge_indices}). Use 'netrun.node_factories.broadcast' to replicate output to multiple targets.",
                        type="fan_out",
                    ))

        # Per-node validation
        for idx, node in enumerate(self.nodes):
            if isinstance(node, NodeConfig):
                node_errors = node.validate()
                for err in node_errors:
                    errors.append(ConfigValidationError(
                        loc=["nodes", idx] + err.loc,
                        msg=err.msg,
                        type=err.type,
                    ))

        return errors

    def has_subgraphs(self) -> bool:
        """Check if this graph contains any subgraphs."""
        return any(isinstance(node, SubgraphConfig) for node in self.nodes)

    def get_graph(self) -> netrun_sim.Graph:
        """Convert this config to a netrun_sim.Graph object.

        Raises:
            ValueError: If graph contains SubgraphConfig nodes. Call resolve() first,
                or if graph validation fails (e.g. fan-out from output ports).
        """
        if self.has_subgraphs():
            raise ValueError(
                "Cannot convert GraphConfig with subgraphs to netrun_sim.Graph. "
                "Call resolve() first to flatten subgraphs."
            )
        # At this point, all nodes are NodeConfig
        nodes = [node.to_netrun_sim() for node in self.nodes]  # type: ignore
        edges = []
        dep_edges = []
        for edge in self.edges:
            sim_edge = edge.to_netrun_sim()
            edges.append(sim_edge)
            if edge.dependency:
                dep_edges.append(sim_edge)
        graph = netrun_sim.Graph(nodes, edges, dependency_edges=dep_edges or None)

        # Validate graph constraints (e.g. no fan-out from output ports)
        errors = graph.validate()
        if errors:
            msgs = [str(e) for e in errors]
            raise ValueError(
                f"Graph validation failed with {len(errors)} error(s):\n"
                + "\n".join(f"  - {m}" for m in msgs)
            )

        return graph
